import exec from "k6/execution";
import { profiles } from "../config/load-profiles.js";

const runConfig = JSON.parse(open("../config/run.config.json"));
const environment = __ENV.K6_ENV || runConfig.environment;
const profileName = __ENV.K6_PROFILE || runConfig.profile;
const testData = JSON.parse(open(`../test-data/${environment}.json`));
if (!profiles[profileName])
  exec.test.abort(
    `Unknown load profile "${profileName}". Available: ${Object.keys(profiles).join(", ")}`,
  );

export const config = Object.freeze({
  environment,
  profileName,
  testData,
  runConfig,
});
export const options = {
  scenarios: { performance: { ...profiles[profileName], exec: "performance" } },
  thresholds: runConfig.thresholds,
  summaryTrendStats: runConfig.summaryTrendStats,
  tags: { environment, profile: profileName },
};
